   segue_manual, observacao, fonte_url, fonte_nome, confianca)
values
  ('vela', 'NGK', 'Velas convencionais (níquel) — referência de vida útil', 'niquel', '{"tipo_intervalo": "troca", "data_fonte": "2022-01-11", "citacao": "podendo variar de 30 mil km (velas convencionais) a 100 mil km (velas de iridium), em alguns modelos", "quem_define": "montadora"}'::jsonb, 30000, null, null, null, false, 'Referência da NGK para vela comum. Quem manda é o plano da montadora; se o manual pedir menos, vale o manual.', 'https://omecanico.com.br/vela-de-ignicao-como-aumentar-sua-vida-util/', 'Revista O Mecânico (declaração da NGK, Hiromori Mori)', 'fabricante'),
  ('vela', 'NGK', 'Velas de irídio de equipamento original', 'iridio', '{"tipo_intervalo": "troca", "data_fonte": "2022-01-11", "aplicacao": "só carros que saem de fábrica com vela de irídio"}'::jsonb, 100000, null, null, null, false, 'Até 100 mil km só em alguns modelos que já vêm com irídio. Confira o manual do carro.', 'https://omecanico.com.br/vela-de-ignicao-como-aumentar-sua-vida-util/', 'Revista O Mecânico (declaração da NGK)', 'fabricante'),
  ('vela', 'NGK', 'Iridium IX (reposição)', 'iridio', '{"tipo_intervalo": "segue_manual", "data_fonte": "2023-05-03"}'::jsonb, null, null, null, null, true, 'A NGK não garante vida maior na reposição: mantenha o intervalo da vela original do carro.', 'https://omecanico.com.br/ngk-esclarece-6-duvidas-frequentes-dos-mecanicos/', 'Revista O Mecânico (NGK)', 'fabricante'),
  ('vela', 'NGK', 'G-Power (platina, reposição)', 'platina', '{"tipo_intervalo": "segue_manual", "data_fonte": "2023-05-03"}'::jsonb, null, null, null, null, true, 'Mesmo sendo de platina, a NGK manda manter o intervalo da vela original do carro.', 'https://omecanico.com.br/ngk-esclarece-6-duvidas-frequentes-dos-mecanicos/', 'Revista O Mecânico (NGK)', 'fabricante'),
  ('vela', 'NGK', 'Inspeção preventiva de velas (todas as linhas)', 'geral', '{"tipo_intervalo": "inspecao", "data_fonte": "2022-01-11"}'::jsonb, 10000, 12, null, null, false, 'Inspeção, não troca: revisar a cada 10 mil km ou 1 vez por ano.', 'https://omecanico.com.br/vela-de-ignicao-como-aumentar-sua-vida-util/', 'Revista O Mecânico (NGK)', 'fabricante'),
  ('vela', 'Bosch', 'Velas de eletrodo comum (níquel ou ítrio)', 'niquel', '{"tipo_intervalo": "troca", "data_fonte": "2016-12-26", "citacao": "se for de material comum (níquel ou ítrio), diminui para aproximadamente 40 mil quilômetros"}'::jsonb, 40000, null, null, null, false, 'Valor aproximado da Bosch. Se o manual pedir menos, siga o manual.', 'https://garagem360.com.br/?p=4676', 'Garagem 360 (atribuído à Bosch)', 'fabricante'),
  ('vela', 'Bosch', 'Velas de eletrodo nobre (platina ou irídio)', 'platina_iridio', '{"tipo_intervalo": "troca", "data_fonte": "2016-12-26", "citacao": "se ele for nobre (irídio ou platina), a vida útil é de cerca de 100 mil quilômetros"}'::jsonb, 100000, null, null, null, false, 'Cerca de 100 mil km segundo a Bosch. Vale para carros projetados para vela nobre.', 'https://garagem360.com.br/?p=4676', 'Garagem 360 (atribuído à Bosch)', 'fabricante'),
  ('vela', 'Bosch', 'Verificação de velas (todas as linhas)', 'geral', '{"tipo_intervalo": "inspecao", "data_fonte": "2018-11-29"}'::jsonb, 10000, null, null, null, false, 'Inspeção a cada 10 mil km; ao trocar vela, testar também o cabo.', 'https://omecanico.com.br/bosch-ressalta-importancia-da-revisao-preventiva-do-sistema-de-ignicao-em-epoca-de-ferias/', 'Revista O Mecânico (Bosch)', 'fabricante'),
  ('oleo_motor', 'Mercado (regra popular)', 'Regra por tipo de base: mineral 5 mil / semi 7,5 mil / sintético 10 mil km', 'geral', '{"tipo_intervalo": "referencia", "data_fonte": "2018-07-03", "regra_popular_km": {"mineral": 5000, "semissintetico": 7500, "sintetico": 10000}, "veredito_da_fonte": "lenda; o intervalo é definido pelo manual"}'::jsonb, null, null, null, null, true, 'Regra de balcão, não do fabricante do óleo. A imprensa chama de lenda: use o manual do carro.', 'https://autopapo.com.br/blog-do-boris/tipo-oleo-prazo-deve-ser-trocado/', 'AutoPapo (Boris Feldman)', 'mercado'),
  ('oleo_motor', 'YPF', 'Linha automotiva (mineral, semi e sintético)', 'geral', '{"tipo_intervalo": "segue_manual", "data_fonte": "2022-09-14", "posicao": "o tipo de base não define a quilometragem"}'::jsonb, null, null, null, null, true, 'YPF: o tipo de óleo não define o prazo; siga o manual do carro.', 'https://omecanico.com.br/fabricante-esclarece-cinco-duvidas-sobre-oleo-lubrificante', 'Revista O Mecânico (YPF Brasil)', 'fabricante'),
  ('oleo_motor', 'TotalEnergies', 'Linha automotiva', 'geral', '{"tipo_intervalo": "segue_manual", "data_fonte": "2018-10-10", "faixa_citada_km": "5.000 ou 10.000 conforme o fabricante do carro"}'::jsonb, null, null, null, null, true, 'Normalmente 5 ou 10 mil km, mas a Total manda seguir à risca o manual.', 'https://omecanico.com.br/total-lubrificantes-explica-quais-cuidados-tomar-nas-trocas-de-oleo/', 'Revista O Mecânico (Total Lubrificantes)', 'fabricante'),
  ('oleo_motor', 'Ipiranga', 'F1 Master Sintético 5W-30 SN', 'sintetico', '{"tipo_intervalo": "segue_manual", "viscosidade": "SAE 5W-30", "api": "SN", "indicacao": "Kia, Nissan, Toyota; serve onde se pede API SM, SL, SJ"}'::jsonb, null, null, null, null, true, 'Ficha técnica não traz prazo: siga o manual do veículo.', 'https://iconic.static-content.fastchannel.com/iconic/media-files/312536_-_Ipiranga_F1_Master_Sintetico_5W30_SN_.pdf', 'Ficha técnica Ipiranga', 'fabricante'),
  ('oleo_motor', 'Mobil', 'Mobil Super 1000 10W-30', 'mineral', '{"tipo_intervalo": "segue_manual", "viscosidade": "SAE 10W-30", "api": "SN, SQ, SQ Resource Conserving", "ilsac": "GF-7A", "uso": "uso diário em condições normais"}'::jsonb, null, null, null, null, true, 'Mineral sem prazo próprio: consulte o manual do carro.', 'https://www.mobil.com/pt-BR/Passenger-Vehicle-Lube/pds/as-xx-Mobil-Super-1000-10W-30', 'Mobil Brasil — ficha do produto', 'fabricante'),
  ('oleo_motor', 'Shell', 'Helix HX6 Flex 15W-40', 'semissintetico', '{"tipo_intervalo": "segue_manual", "viscosidade": "SAE 15W-40", "api": "SL"}'::jsonb, null, null, null, null, true, 'Ficha técnica sem prazo de troca: siga o manual (Shell indica o LubeMatch).', 'https://raizenlubrificantes.shell.com.br/shell/uploads/downloads_item/2741-shell_helix_h_x6_f_l_e_x_s_l15_w40.pdf', 'Ficha técnica Shell/Raízen', 'fabricante'),
  ('oleo_motor', 'Shell', 'Helix Ultra SN 5W-20', 'sintetico', '{"tipo_intervalo": "segue_manual", "viscosidade": "SAE 5W-20", "api": "SN", "ilsac": "GF-5", "acea": "A1/B1", "oem": "Chrysler 6395, GM 6094M, Ford WSS-M2C945-A e M2C930-A"}'::jsonb, null, null, null, null, true, 'Sem prazo próprio: siga o manual do carro.', 'https://raizenlubrificantes.shell.com.br/shell/uploads/downloads_item/3971-shell_helix_ultra_s_n5_w20.pdf', 'Ficha técnica Shell/Raízen', 'fabricante'),
  ('oleo_motor', 'Shell', 'Helix Ultra Professional AG 0W-20', 'sintetico', '{"tipo_intervalo": "segue_manual", "viscosidade": "SAE 0W-20", "api": "SP", "ilsac": "GF-6A", "oem": "GM dexos1 Gen 3"}'::jsonb, null, null, null, null, true, 'Atende GM dexos1 Gen 3. Prazo de troca: o do manual.', 'https://raizenlubrificantes.shell.com.br/shell/uploads/downloads_item/2957-shell_helix_ultra_pro_a_g0_w20.pdf', 'Ficha técnica Shell/Raízen', 'fabricante'),
  ('oleo_motor', 'Lubrax', 'Top Turbo Pro S 10W-40 (diesel)', 'sintetico', '{"tipo_intervalo": "segue_manual", "viscosidade": "SAE 10W-40", "normas": "API CI-4, ACEA E7, Volvo VDS-3, MTU Tipo 3.1, MAN M 3477 e M 3271, Cummins CES 20077, Caterpillar ECF-1a", "posicao": "permite intervalo estendido conforme o fabricante do equipamento"}'::jsonb, null, null, null, null, true, 'Permite intervalo estendido, mas o prazo é o do fabricante do motor.', 'https://www.lubrax.com.br/sites/lubrax/files/2024-07/pt_lubrax_lubrax_top_turbo_pro_s_0.pdf', 'Ficha técnica Lubrax', 'fabricante'),
  ('oleo_motor', 'Chevrolet (exigência da montadora)', 'Onix/Onix Plus 1.0 e 1.0 turbo com correia banhada (2019/2020 em diante)', 'geral', '{"tipo_intervalo": "troca", "data_fonte": "2025-09-15", "norma": "dexos1 Gen 3", "viscosidade": "0W-20 (aspirado) ou 5W-30 (turbo)", "motivo": "condição da garantia de até 240 mil km da correia banhada"}'::jsonb, 10000, 12, null, null, false, 'Trocar a cada 10 mil km ou 1 ano com óleo dexos1 Gen 3; é condição da garantia da correia banhada.', 'https://garagem360.com.br/?p=290462', 'Garagem 360 (campanha Chevrolet)', 'fabricante'),
  ('oleo_motor', 'Ford (exigência da montadora)', 'Ka 1.0 3 cilindros com correia banhada', 'geral', '{"tipo_intervalo": "segue_manual", "data_fonte": "2019-10-03", "viscosidade": "5W-20", "norma": "Ford WSS-M2C948-B"}'::jsonb, null, null, null, null, true, 'Use 5W-20 Ford WSS-M2C948-B no prazo do manual; disso depende a correia de 240 mil km.', 'https://omecanico.com.br/motor-substituicao-da-correia-dentada-embebida-em-oleo/', 'Revista O Mecânico', 'fabricante'),
  ('oleo_motor', 'Imprensa (VRUM)', 'Uso severo — qualquer tipo de óleo', 'geral', '{"tipo_intervalo": "troca", "data_fonte": "2024-11-07", "uso_severo": "trânsito intenso, trajetos curtos, clima extremo, estrada de terra", "faixa_geral_fabricantes_km": "5.000 a 10.000"}'::jsonb, null, 12, 5000, null, false, 'Em uso severo, trocar a cada 5 mil km; mesmo rodando pouco, pelo menos 1 vez por ano.', 'https://www.vrum.com.br/aceleradas/2024/11/6983561-quando-devo-trocar-o-oleo-do-carro.html', 'Portal VRUM', 'imprensa'),
  ('filtro_oleo', 'Mann-Filter', 'Filtros de óleo (linha leve)', 'geral', '{"tipo_intervalo": "acompanha_outro_servico", "acompanha": "troca de óleo", "data_fonte": "2019-02-26"}'::jsonb, null, null, null, null, true, 'Trocar sempre junto com o óleo, no prazo do manual.', 'https://omecanico.com.br/mann-filter-recomenda-manutencao-preventiva-dos-filtros-antes-do-carnaval/', 'Revista O Mecânico (Mann-Filter)', 'fabricante'),
  ('filtro_oleo', 'Wega', 'Filtros (orientação geral da marca)', 'geral', '{"tipo_intervalo": "troca", "data_fonte": "2019-09-10", "citacao": "A empresa recomenda a verificação e substituição dos filtros a cada 10 mil km"}'::jsonb, 10000, null, null, null, false, 'Wega: verificar e trocar os filtros a cada 10 mil km. O manual do carro prevalece.', 'https://omecanico.com.br/wega-alerta-para-manutencao-preventiva-dos-filtros-na-autonor-2019/', 'Revista O Mecânico (Wega)', 'fabricante'),
  ('filtro_ar', 'Mann-Filter', 'Filtro de ar (carros de passeio)', 'geral', '{"tipo_intervalo": "troca", "data_fonte": "2009-02-16", "faixa_km": "10.000 a 15.000", "valor_usado": "limite inferior da faixa"}'::jsonb, 10000, 12, null, null, false, 'Mann: trocar entre 10 e 15 mil km ou no máximo após 1 ano de uso.', 'https://motonline.com.br/noticia/manutencao-preventiva-dos-filtros-do-veiculo-e-fundamental-para-o-seu-bom-funcionamento/', 'Motonline (MANN+HUMMEL)', 'fabricante'),
  ('filtro_ar', 'Wega', 'Filtro de ar', 'geral', '{"tipo_intervalo": "inspecao", "data_fonte": "2019-02-21"}'::jsonb, 10000, null, null, null, false, 'Verificar a cada 10 mil km; estrada de terra pede mais atenção.', 'https://omecanico.com.br/wega-alerta-para-manutencao-preventiva-dos-filtros-de-ar-e-cabine/', 'Revista O Mecânico (Wega)', 'fabricante'),
  ('filtro_ar', 'Tecfil', 'Filtro de ar', 'geral', '{"tipo_intervalo": "segue_manual", "data_fonte": "2022-05-10"}'::jsonb, null, null, null, null, true, 'Tecfil: trocar conforme o manual do proprietário, não só quando estiver sujo.', 'https://omecanico.com.br/alto-consumo-pode-ser-problema-no-filtro-de-ar', 'Revista O Mecânico (Tecfil)', 'fabricante'),
  ('filtro_ar', 'Bosch', 'Filtro de ar', 'geral', '{"tipo_intervalo": "segue_manual", "data_fonte": "2008-09-01"}'::jsonb, null, null, null, null, true, 'Seguir o manual; antecipar em estrada de terra ou cidade muito poluída.', 'https://mecanicaonline.com.br/2008/09/filtros-requerem-cuidados-especiais-2/', 'Mecânica Online (Bosch)', 'fabricante'),
  ('filtro_cabine', 'Mann-Filter', 'Filtro de cabine (uso normal)', 'geral', '{"tipo_intervalo": "troca", "data_fonte": "2020-04-13"}'::jsonb, 15000, 12, null, null, false, 'Uma vez por ano ou 15 mil km. Trânsito pesado ou terra pode saturar em poucos meses.', 'https://omecanico.com.br/filtro-de-cabine-nao-pode-ficar-de-lado/', 'Revista O Mecânico (Mann-Filter)', 'fabricante'),
  ('filtro_cabine', 'Bosch', 'Filtros de cabine (orientação global)', 'geral', '{"tipo_intervalo": "troca", "citacao": "once a year or every 15,000 km"}'::jsonb, 15000, 12, null, null, false, 'Bosch: trocar 1 vez por ano ou a cada 15 mil km.', 'https://www.boschaftermarket.com/xrm/media/images/services/news_3/23_11_bosch_filters/bosch_filter_change_for_passenger_cars.pdf', 'Bosch Aftermarket (PDF)', 'fabricante'),
  ('filtro_cabine', 'Bosch', 'Filtro de cabine (orientação Brasil)', 'geral', '{"tipo_intervalo": "troca", "data_fonte": "2008-09-01"}'::jsonb, 10000, 12, null, null, false, 'Bosch Brasil: a cada 10 mil km ou pelo menos 1 vez por ano.', 'https://mecanicaonline.com.br/2008/09/filtros-requerem-cuidados-especiais-2/', 'Mecânica Online (Bosch)', 'fabricante'),
  ('filtro_cabine', 'Tecfil', 'Filtro de cabine / ar-condicionado', 'geral', '{"tipo_intervalo": "troca", "data_fonte": "2020-03-03", "faixa_meses_urbano": "6 a 12 (no máximo)"}'::jsonb, null, 12, null, null, false, 'Uso urbano: trocar entre 6 meses e 1 ano, no máximo. Muita poeira: antes disso.', 'https://omecanico.com.br/tecfil-alerta-para-riscos-da-falta-de-troca-do-filtro-de-ar-condicionado/', 'Revista O Mecânico (Tecfil)', 'fabricante'),
  ('filtro_cabine', 'Wega', 'Filtro de cabine', 'geral', '{"tipo_intervalo": "inspecao", "data_fonte": "2019-02-21"}'::jsonb, 10000, null, null, null, false, 'Verificar a cada 10 mil km; uso constante do ar e poeira desgastam mais.', 'https://omecanico.com.br/wega-alerta-para-manutencao-preventiva-dos-filtros-de-ar-e-cabine/', 'Revista O Mecânico (Wega)', 'fabricante'),
  ('filtro_combustivel', 'Mann-Filter', 'Filtro de combustível (média de mercado)', 'geral', '{"tipo_intervalo": "troca", "data_fonte": "2013-08-22 (atualizado 2022-11-08)", "faixa_montadoras_km": "10.000 a 15.000"}'::jsonb, 10000, null, null, null, false, 'Média de 10 mil km; montadoras pedem entre 10 e 15 mil. Uso urbano: antecipar.', 'https://www.portaldotransito.com.br/noticias/filtro-de-combustivel-deve-ser-trocado-para-eliminar-impurezas-do-alcool-2/', 'Portal do Trânsito (MANN+HUMMEL)', 'fabricante'),
  ('filtro_combustivel', 'Mann-Filter', 'Filtro de combustível (limite por tempo)', 'geral', '{"tipo_intervalo": "troca", "data_fonte": "2009-02-16"}'::jsonb, null, 12, null, null, false, 'Km conforme o fabricante do carro, mas no máximo 1 ano.', 'https://motonline.com.br/noticia/manutencao-preventiva-dos-filtros-do-veiculo-e-fundamental-para-o-seu-bom-funcionamento/', 'Motonline (MANN+HUMMEL)', 'fabricante'),
  ('filtro_combustivel', 'Bosch', 'Filtro de combustível', 'geral', '{"tipo_intervalo": "segue_manual", "data_fonte": "2008-09-01"}'::jsonb, null, null, null, null, true, 'Bosch: trocar no intervalo definido pela montadora.', 'https://mecanicaonline.com.br/2008/09/filtros-requerem-cuidados-especiais-2/', 'Mecânica Online (Bosch)', 'fabricante'),
  ('filtro_combustivel', 'Wega', 'Filtro de combustível', 'geral', '{"tipo_intervalo": "troca", "data_fonte": "2019-09-10"}'::jsonb, 10000, null, null, null, false, 'Wega: verificar e trocar os filtros a cada 10 mil km.', 'https://omecanico.com.br/wega-alerta-para-manutencao-preventiva-dos-filtros-na-autonor-2019/', 'Revista O Mecânico (Wega)', 'fabricante'),
  ('bateria', 'Moura', 'Linha automotiva (convencional, EFB, AGM)', 'geral', '{"tipo_intervalo": "garantia", "garantia_meses": "até 24", "efb_agm": "fabricante diz ''3 vezes mais ciclos''"}'::jsonb, null, null, null, null, false, 'Garantia de até 24 meses conforme modelo. A Moura não informa vida útil em meses.', 'https://www.moura.com.br/produtos/baterias-para-veiculos-leves', 'Moura — site oficial', 'fabricante'),
  ('bateria', 'Moura', 'M50JD 50Ah', 'chumbo_acido_convencional', '{"tipo_intervalo": "garantia", "garantia_meses": 18}'::jsonb, null, null, null, null, false, 'Garantia de 18 meses. Use como lembrete de teste; não é vida útil.', 'https://www.casasbahia.com.br/bateria-moura-m50jd-50ah-18-meses-de-garantia/p/14774155', 'Casas Bahia (anúncio com dados do fabricante)', 'fabricante'),
  ('bateria', 'Zetta (Moura)', 'Z60D 60Ah livre de manutenção', 'chumbo_acido_convencional', '{"tipo_intervalo": "garantia", "garantia_meses": 12, "fabricante": "Moura"}'::jsonb, null, null, null, null, false, 'Garantia de 12 meses contra defeito de fabricação.', 'https://www.casasbahia.com.br/bateria-zetta-livre-de-manutencao-12v-60ah-z60d-verona-versailles-chevette-corsa-classic-ipanema/p/1565429371', 'Casas Bahia (anúncio com dados do fabricante)', 'fabricante'),
  ('bateria', 'Heliar', 'Heliar Racing (48, 52, 65 e 75 Ah)', 'geral', '{"tipo_intervalo": "garantia", "garantia_meses": 24, "data_fonte": "2011-06-21 (atualizado 2020-01-17)"}'::jsonb, null, null, null, null, false, 'Garantia de 24 meses. Confirme se a linha ainda é vendida.', 'https://omecanico.com.br/heliar-lanca-bateria-para-veiculos-com-elevado-conteudo-eletronico/', 'Revista O Mecânico (Heliar)', 'fabricante'),
  ('bateria', 'Heliar', 'EFB para start-stop (reposição)', 'EFB', '{"tipo_intervalo": "referencia", "data_fonte": "2018-04-16", "durabilidade": "até 2 vezes a das baterias convencionais"}'::jsonb, null, null, null, null, false, 'Sem prazo em meses. Bateria indicada para carros com start-stop; dura até 2x a convencional.', 'https://www.autodata.com.br/news/2018/04/16/reposicao-ja-tem-bateria-heliar-para-start-stop/26611/', 'AutoData (Heliar)', 'fabricante'),
  ('bateria', 'Bosch', 'Linha S5 e S6', 'geral', '{"tipo_intervalo": "garantia", "garantia_meses": "18 a 24 conforme modelo", "data_fonte": "2018-09-06"}'::jsonb, null, null, null, null, false, 'Garantia de 18 a 24 meses conforme o modelo.', 'https://omecanico.com.br/bosch-aprimora-linha-de-baterias-automotivas/', 'Revista O Mecânico (Bosch)', 'fabricante'),
  ('bateria', 'Bosch', 'Teste de bateria (qualquer linha)', 'geral', '{"tipo_intervalo": "inspecao", "vida_util_tipica": "fraqueja em 3–5 anos; após 4–5 anos a troca costuma ser necessária", "mercado": "Reino Unido (Bosch Car Service)"}'::jsonb, null, 12, null, null, false, 'Testar a bateria pelo menos 1 vez por ano; com mais de 4 anos, avisar o cliente.', 'https://www.boschcarservice.com/gb/en/services/electronic-services/battery-check/', 'Bosch Car Service (Reino Unido)', 'fabricante'),
  ('bateria', 'Bosch', 'Vida útil de referência (Brasil)', 'geral', '{"tipo_intervalo": "referencia", "data_fonte": "2016-07-11", "vida_util": "três anos ou mais com boa manutenção"}'::jsonb, null, null, null, null, false, 'Bateria boa e com manutenção elétrica em dia pode durar 3 anos ou mais. Teste no frio.', 'https://omecanico.com.br/bosch-explica-por-que-e-importante-verificar-a-bateria-durante-o-inverno/', 'Revista O Mecânico (Bosch)', 'fabricante'),
  ('bateria', 'Imprensa (AutoPapo)', 'Bateria automotiva comum', 'geral', '{"tipo_intervalo": "vida_util", "data_fonte": "2018-07-05", "faixa_meses": "24 a 36", "valor_usado": "limite inferior da faixa", "garantias_de_mercado": "1 ano a 2 anos"}'::jsonb, null, 24, null, null, false, 'Vida média de 2 a 3 anos; muitas chegam a 4–5. Use como alerta de teste.', 'https://autopapo.com.br/blog-do-boris/quanto-tempo-dura-bateria-automotiva/', 'AutoPapo (Boris Feldman)', 'imprensa'),
