  ('correia_dentada', 'Volkswagen', 'Motor EA111 1.0 8V (Gol, Fox, Polo, Saveiro)', 'correia_seca', '{"tipo_intervalo": "troca", "data_fonte": "2026-01-27", "kit": "rolamentos de apoio e tensionadores"}'::jsonb, 60000, null, null, null, false, 'A cada 60 mil km, junto com tensionadores e rolamentos.', 'https://omecanico.com.br/guia-pratico-troca-da-correia-de-sincronismo-no-vw-gol-1-0-ea-111/', 'Revista O Mecânico (montadora)', 'fabricante'),
  ('correia_dentada', 'Chevrolet', 'Onix/Onix Plus 1.0 turbo (correia banhada a óleo)', 'correia_banhada_oleo', '{"tipo_intervalo": "troca", "data_fonte": "2024-06-02", "oleo": "dexos1 Gen 3: 5W-30 (turbo), 0W-20 (aspirado)"}'::jsonb, 240000, 180, null, null, false, 'Manual: 240 mil km ou 15 anos, mas há relatos de falha antes de 50 mil km. Óleo certo e revisões em dia.', 'https://omecanico.com.br/troca-da-correia-sincronizadora-banhada-em-oleo-do-onix-e-complexa-que-requer-atencao-para-ser-feita-parte-1/', 'Revista O Mecânico (manual Chevrolet)', 'fabricante'),
  ('correia_dentada', 'Chevrolet', 'Motor 1.0 com correia banhada (Onix, Onix Plus, Tracker, Montana — 2020 em diante)', 'correia_banhada_oleo', '{"tipo_intervalo": "troca", "data_fonte": "2024-11-25", "garantia": "240.000 km sem limite de tempo (antes: 3 anos ou 100.000 km)", "oleo": "dexos1 Gen 3"}'::jsonb, 240000, null, null, null, false, 'Troca prevista aos 240 mil km; garantia vale só com revisões e óleo dexos1 Gen 3.', 'https://www.vrum.com.br/noticias/2024/11/6996151-chevrolet-da-garantia-de-240-mil-km-para-polemica-correia-banhada-a-oleo.html', 'Portal VRUM (Chevrolet)', 'fabricante'),
  ('correia_dentada', 'Chevrolet', 'Onix/Onix Plus 2026 (nova correia banhada com fibra de vidro)', 'correia_banhada_oleo', '{"tipo_intervalo": "troca", "data_fonte": "2025-08-15", "oleo": "dexos1 Gen 2 ou superior (segundo a matéria)"}'::jsonb, 240000, 120, null, null, false, 'Vida estimada de 240 mil km ou 10 anos, seguindo as trocas de óleo em dia.', 'https://www.vrum.com.br/noticias/2025/08/7227031-onix-2026-nova-correia-dentada-banhada-a-oleo-roda-ate-240-mil-km.html', 'Portal VRUM (Chevrolet)', 'fabricante'),
  ('correia_dentada', 'Ford', 'Ka 1.0 3 cilindros (correia banhada a óleo)', 'correia_banhada_oleo', '{"tipo_intervalo": "troca", "data_fonte": "2019-10-03", "oleo": "5W-20 Ford WSS-M2C948-B", "condicao": "trocas de óleo no prazo e com o lubrificante especificado"}'::jsonb, 240000, null, null, null, false, '240 mil km só com o óleo especificado trocado no prazo; desgaste precoce aparece quando isso falha.', 'https://omecanico.com.br/motor-substituicao-da-correia-dentada-embebida-em-oleo/', 'Revista O Mecânico (Ford)', 'fabricante'),
  ('correia_dentada', 'Fiat', 'Motor Fire 1.0 8V (ex.: Palio 2010/2011)', 'correia_seca', '{"tipo_intervalo": "troca", "data_fonte": "2015-08-06", "inspecao_sugerida": "~15.000 km"}'::jsonb, 60000, null, null, null, false, 'Manual indica troca preventiva aos 60 mil km; checar o sistema por volta de 15 mil km.', 'https://omecanico.com.br/substituicao-da-sincronizadora-no-fire-1-0/', 'Revista O Mecânico (manual Fiat)', 'fabricante'),
