  ('correia_dentada', 'Continental (ContiTech)', 'Correias sincronizadoras (kit)', 'geral', '{"tipo_intervalo": "segue_manual", "data_fonte": "2021-09-09", "regra": "trocar tensor junto com a correia"}'::jsonb, null, null, null, null, true, 'Prazo do manual; sempre trocar o tensor junto com a correia.', 'https://omecanico.com.br/continental-fala-sobre-troca-do-tensor-com-a-correia/', 'Revista O Mecânico (Continental)', 'fabricante'),
