  ('pastilha_freio', 'TMD Friction (Cobreq/Textar)', 'Pastilhas em geral', 'geral', '{"tipo_intervalo": "limite_de_desgaste", "data_fonte": "2020-08-04", "espessura_minima_atrito_mm": 2}'::jsonb, null, null, null, null, false, 'Fim de vida com 2 mm ou menos de atrito; checar o disco a cada troca.', 'https://omecanico.com.br/como-saber-se-a-pastilha-de-freio-esta-no-fim-da-sua-vida-util/', 'Revista O Mecânico (TMD Friction)', 'fabricante'),
