  ('pneu', 'Pirelli', 'Pneus de carro — rodízio', 'geral', '{"tipo_intervalo": "rodizio", "faixa_km": "5.000 a 10.000 conforme o uso", "valor_usado": "limite inferior da faixa", "condicao": "só em carros com a mesma medida nos 4 pneus", "calibragem": "pelo menos 1 vez por semana e antes de viajar", "garantia": "5 anos da data de compra (com nota fiscal)", "idade": "inspeção periódica, principalmente com mais de 5 anos de fabricação", "sulco_minimo_mm": 1.6}'::jsonb, 5000, null, null, null, false, 'Rodízio entre 5 e 10 mil km; calibrar toda semana com pneu frio. TWI 1,6 mm (Res. CONTRAN 913/2022).', 'https://pirelli.com/tyres/pt-br/carro/manual-de-uso-e-garantia', 'Pirelli Brasil — Manual de uso e garantia', 'fabricante'),
  ('pneu', 'Pirelli', 'Pneus de carro — alinhamento e balanceamento', 'geral', '{"tipo_intervalo": "inspecao", "faixa_km": "5.000 a 10.000", "valor_usado": "limite inferior da faixa"}'::jsonb, 5000, null, null, null, false, 'Verificar alinhamento e balanceamento entre 5 e 10 mil km, e após buracos ou vibração.', 'https://pirelli.com/tyres/pt-br/carro/manual-de-uso-e-garantia', 'Pirelli Brasil — Manual de uso e garantia', 'fabricante'),
  ('pneu', 'Pirelli', 'Pneus com 10 anos ou mais de fabricação', 'geral', '{"tipo_intervalo": "troca_por_idade", "data_fonte": "2018-10-11"}'::jsonb, null, 120, null, null, false, 'Substituir por precaução pneus com 10 anos ou mais da data de fabricação (DOT).', 'https://mecanicaonline.com.br/2018/10/saiba-as-diferencas-entre-validade-e-garantia-dos-pneus/', 'Mecânica Online (Pirelli)', 'fabricante'),
  ('pneu', 'Michelin', 'Pneus (inclusive estepe) — idade máxima', 'geral', '{"tipo_intervalo": "troca_por_idade", "data_fonte": "2022-07-20"}'::jsonb, null, 120, null, null, false, 'Trocar 10 anos após a fabricação, mesmo com sulco bom; vale para o estepe.', 'https://canaltech.com.br/carros/quanto-tempo-dura-um-pneu-sem-comprometer-a-seguranca-do-carro-221217/', 'Canaltech (citando o site da Michelin)', 'fabricante'),
  ('pneu', 'Goodyear', 'Pneus de passeio — rodízio e calibragem', 'geral', '{"tipo_intervalo": "rodizio", "calibragem": "semanal, com pneus frios", "alinhamento_balanceamento_km": "no máximo a cada 5.000", "sulco_minimo_mm": 1.6, "garantia": "5 anos pela nota fiscal; sem nota, conta da data DOT (3 meses legal + 4 anos e 9 meses contratual)", "idade": "sem limite fixo; trocar com trincas, rachaduras ou borracha endurecida"}'::jsonb, 5000, null, null, null, false, 'Rodízio a cada 5 mil km; alinhar e balancear no máximo a cada 5 mil km.', 'https://images.goodyear.com.br/content-uploads/www.goodyear.com.br/certificado-garantia-goodyear-final.pdf', 'Goodyear Brasil — certificado de garantia', 'fabricante'),
  ('pneu', 'Goodyear', 'Alinhamento e balanceamento', 'geral', '{"tipo_intervalo": "inspecao", "data_fonte": "2019-01-11", "sulco_minimo_mm": 1.6}'::jsonb, 5000, 6, null, null, false, 'A cada 5 mil km ou 6 meses. Abaixo de 1,6 mm de sulco, trocar o pneu.', 'https://omecanico.com.br/alinhamento-e-balanceamento-se-faz-cada-5-mil-km-ou-6-meses-explica-goodyear/', 'Revista O Mecânico (Goodyear)', 'fabricante'),
  ('amortecedor', 'Monroe', 'Amortecedores', 'geral', '{"tipo_intervalo": "inspecao", "data_fonte": "2019-01-31", "regra": "40.000 km não é regra rígida; trocar em pares"}'::jsonb, 10000, null, null, null, false, 'Revisar no máximo a cada 10 mil km; não há km fixa de troca. Trocar sempre em pares.', 'https://omecanico.com.br/monroe-da-10-dicas-de-manutencao-preventiva-de-amortecedores/', 'Revista O Mecânico (Monroe/Tenneco)', 'fabricante'),
  ('amortecedor', 'Cofap', 'Amortecedores', 'geral', '{"tipo_intervalo": "inspecao", "data_fonte": "2025-02-17"}'::jsonb, 20000, 12, null, null, false, 'Cofap recomenda verificar a cada 20 mil km ou 12 meses, conforme o uso.', 'https://garagem360.com.br/?p=278349', 'Garagem 360 (Cofap Aftermarket)', 'fabricante'),
  ('amortecedor', 'Nakata', 'Amortecedores (após 40 mil km)', 'geral', '{"tipo_intervalo": "inspecao", "data_fonte": "2016-07-18", "inicio_km": 40000}'::jsonb, 10000, null, null, null, false, 'Depois dos 40 mil km, revisar os amortecedores a cada 10 mil km.', 'https://omecanico.com.br/nakata-enumera-fatores-que-podem-prejudicar-os-amortecedores/', 'Revista O Mecânico (Nakata)', 'fabricante'),
  ('amortecedor', 'Nakata', 'Regra de substituição', 'geral', '{"tipo_intervalo": "regra_de_troca", "data_fonte": "2019-01-18", "regra": "trocar em pares, com batentes novos, e alinhar depois"}'::jsonb, null, null, null, null, true, 'Sem km fixa: troque em pares, com batentes novos, e faça alinhamento depois.', 'https://omecanico.com.br/nakata-da-dicas-para-realizar-o-diagnostico-do-sistema-de-suspensao/', 'Revista O Mecânico (Nakata)', 'fabricante'),
