  ('fluido_cambio', 'ZF Aftermarket', 'Kits de troca de óleo de câmbio automático', 'ATF', '{"tipo_intervalo": "segue_manual", "encurtar_em": "viagens rápidas frequentes, reboque, direção esportiva, trajetos curtos"}'::jsonb, null, null, null, null, true, 'Prazo pela Lista de Lubrificantes ZF; encurtar em uso severo.', 'https://aftermarket.zf.com/en/aftermarket-portal/knowledge-hub/inbrief-zf-oil-change-kits/', 'ZF Aftermarket — Knowledge Hub', 'fabricante'),
  ('fluido_cambio', 'Valvoline', 'MaxLife Multi-Vehicle ATF', 'ATF', '{"tipo_intervalo": "segue_manual", "licenca_oem": "não é licenciado por montadora", "restricoes": "não usar na maioria dos câmbios de dupla embreagem nem onde se pede Ford Type F; em CVT só embalagens a partir de maio/2021 (ver ficha)"}'::jsonb, null, null, null, null, true, 'Sem prazo próprio: siga a montadora. Cuidado em CVT e dupla embreagem.', 'https://petroleumservicecompany.com/content/pdfs/Valvoline-Maxlife_MV_ATF_PDS.pdf', 'Ficha técnica Valvoline (distribuidor)', 'fabricante'),
