  ('fluido_cambio', 'Honda', 'Câmbio CVT (modelos atuais)', 'CVT', '{"tipo_intervalo": "troca", "data_fonte": "2026-03-12"}'::jsonb, 40000, null, null, null, false, 'Honda indica troca do fluido do CVT a cada 40 mil km nos carros atuais.', 'https://autopapo.com.br/noticia/oleo-cambio-automatico/', 'AutoPapo (citando a Honda)', 'fabricante'),
